from networkx import Graph
import networkx as nx

g = nx.Graph()
for i in range(24):
    g.add_node(i)

# Add edges to ensure every vertex has degree between 3 and 6
for i in range(24):
    for j in range(i+1, 24):
        if len(list(g.neighbors(i))) < 6 and len(list(g.neighbors(j))) < 6:
            g.add_edge(i, j)
            if len(list(g.neighbors(i))) == 6 or len(list(g.neighbors(j))) == 6:
                break

# Check if the girth (shortest cycle) is at least 7
if nx.girth(g) >= 7:
    print("SATISFIABLE")
    print(list(g.edges))
else:
    print("UNSATISFIABLE")
